// Given: demo 1 (Module 1). Do not edit this file.
// Top: visual V1, explicit vs semi-implicit Euler on a spring (runs without your code).
// Bottom: your createBody and integrate dropping three bodies, with debug draw.
import { createBody } from "../dynamics/body";
import { integrate } from "../dynamics/integrate";
import { clear, drawBody, drawMessage } from "../render/debugDraw";
import { startLoop } from "../render/loop";
import { createView } from "../render/view";
import { createEulerEnergyVisual } from "../visuals/eulerEnergy";
import { mountCanvas, todoBox } from "./ui";
import type { Demo } from "./types";

export const demo1: Demo = {
  title: "Demo 1: bodies and integration",
  description:
    "V1 compares the two Euler schemes on a spring. Below, your Exercise 1 code drops a circle, a box and a spinning box. Space pauses, S steps once.",
  mount(container) {
    const cleanups: Array<() => void> = [createEulerEnergyVisual(container)];
    try {
      const bodies = [
        createBody(
          { shape: { kind: "circle", radius: 0.5 }, position: { x: -3, y: 4 }, mass: 1 },
          0,
        ),
        createBody(
          {
            shape: { kind: "box", halfWidth: 0.5, halfHeight: 0.5 },
            position: { x: 0, y: 4 },
            mass: 1,
          },
          1,
        ),
        createBody(
          {
            shape: { kind: "box", halfWidth: 0.8, halfHeight: 0.3 },
            position: { x: 3, y: 4 },
            mass: 1,
            angularVelocity: 2,
          },
          2,
        ),
      ];
      const start = bodies.map((b) => ({ ...b.position }));
      const view = createView(mountCanvas(container, 320), {
        center: { x: 0, y: 1 },
        pixelsPerMetre: 40,
      });
      const gravity = { x: 0, y: -9.81 };
      const loop = startLoop({
        step: (dt) => {
          for (const b of bodies) integrate(b, dt, gravity);
          // No collisions yet (Module 4): reset bodies once they fall off screen.
          bodies.forEach((b, i) => {
            if (b.position.y < -4) {
              b.position = { ...start[i]! };
              b.linearVelocity = { x: 0, y: 0 };
            }
          });
        },
        render: () => {
          clear(view);
          for (const b of bodies) drawBody(view, b);
          drawMessage(view, "Falling with your integrate(). No collisions until Module 4.");
        },
      });
      cleanups.push(bindKeys(loop), () => loop.stop());
    } catch (e) {
      container.appendChild(todoBox(e));
    }
    return () => cleanups.forEach((c) => c());
  },
};

export function bindKeys(loop: { toggle(): void; stepOnce(): void }): () => void {
  const onKey = (e: KeyboardEvent) => {
    if (e.target instanceof HTMLElement && e.target.closest("input, select, .pfs-player")) return;
    if (e.key === " ") {
      loop.toggle();
      e.preventDefault();
    } else if (e.key === "s") {
      loop.stepOnce();
    }
  };
  window.addEventListener("keydown", onKey);
  return () => window.removeEventListener("keydown", onKey);
}
